package com.company.platform.intake;

import com.company.platform.*;
import com.company.platform.storage.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.*;
import java.io.*;
import java.util.*;

/** 扫描服务复用公共分片、双副本及检测设施；每轮上传冻结明细和目录版本。 */
@Service
public class ScanUpload {
    /** 慢文件读写、病毒检查和 PDF 解析在数据库事务外运行。 */
    private final Sql db;private final ScanIntake intake;private final StorageFiles files;private final FileScanEngine scanner;private final ReadingRuntime runtime;private final TransactionTemplate tx;
    /** 检测器专用身份与调度开关；模拟验收关闭调度后显式执行任务。 */
    private final String scannerId;private final boolean enabled;
    public ScanUpload(Sql db,ScanIntake intake,StorageFiles files,FileScanEngine scanner,ReadingRuntime runtime,PlatformTransactionManager manager,@Value("${platform.scanner.archive-service-id:}") String scannerId,@Value("${platform.scan-intake.worker-enabled:true}") boolean enabled){this.db=db;this.intake=intake;this.files=files;this.scanner=scanner;this.runtime=runtime;this.tx=new TransactionTemplate(manager);this.scannerId=scannerId;this.enabled=enabled;}
    /** 创建设备分片会话；同一稳定操作号不能重新指向另一档案或另一轮返工。 */
    @Transactional
    public Map<String,Object> create(UUID service,UUID operation,Map<String,Object> body){
        Inputs.only(body,"batchId","itemId","originalName","expectedSize","expectedSha256","expectedMediaType");UUID batch=Inputs.uuid(body.get("batchId")),itemId=Inputs.uuid(body.get("itemId"));var scope=intake.serviceBatch(service,batch,true,true);var item=db.required("SELECT * FROM archive.scan_item WHERE id=? AND batch_id=? FOR UPDATE",itemId,batch);if(!Set.of("WAITING","REWORK").contains(item.get("state")))throw ApiFault.conflict("该项已经接收，请按人工返工结论开始新一轮");var record=intake.record((UUID)item.get("record_id"),(UUID)scope.get("department_id"),true);
        var spec=UploadRules.spec(Sql.map("module","ARCHIVE","purpose","ARCHIVE_PDF","businessContextId",itemId.toString(),"originalName",body.get("originalName"),"expectedSize",body.get("expectedSize"),"expectedSha256",body.get("expectedSha256"),"expectedMediaType",body.get("expectedMediaType")));String key="SCAN:"+operation,digest=Crypto.hash(Crypto.json(body));
        db.rows("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",service+":"+key);var prior=db.one("SELECT * FROM storage.upload_session WHERE service_identity_id=? AND idempotency_key=?",service,key);if(prior!=null){if(!Crypto.equal(digest,(String)prior.get("request_digest")))throw ApiFault.conflict("同一操作号不能更换扫描文件");return status(service,(UUID)prior.get("id"));}
        UUID upload=UUID.randomUUID();files.get();db.update("INSERT INTO storage.upload_session(id,module,business_context_id,service_identity_id,expected_sha256,expected_size,expected_media_type,idempotency_key,request_digest,expires_at,purpose,original_name) VALUES(?,'ARCHIVE',?,?,?,?,?,?,?,CURRENT_TIMESTAMP+interval '24 hours','ARCHIVE_PDF',?)",upload,itemId,service,spec.sha256(),spec.size(),spec.mediaType(),key,digest,spec.name());
        db.update("INSERT INTO archive.scan_upload_binding(upload_session_id,item_id,generation,item_version,record_version) VALUES(?,?,?,?,?)",upload,itemId,item.get("generation"),item.get("row_version"),record.get("row_version"));return status(service,upload);
    }
    /** 仅当前设备读取自己的会话，返回分片摘要供断网后核对重试。 */
    public Map<String,Object> status(UUID service,UUID id){var row=session(service,id,false,false);var view=Sql.view(row,"id,state,result_code,object_id,expected_size,expected_sha256,part_size,expires_at,job_id");view.put("parts",db.rows("SELECT part_no,sha256,byte_size FROM storage.upload_part WHERE upload_session_id=? ORDER BY part_no",id).stream().map(part->Sql.view(part,"part_no,sha256,byte_size")).toList());if(row.get("job_id")!=null)view.put("jobState",db.required("SELECT state FROM ops.job WHERE id=?",row.get("job_id")).get("state"));return view;}
    /** 分片接收在锁外刷盘，事务内重验设备和固定轮次；重复分片必须摘要完全一致。 */
    public Map<String,Object> part(UUID service,UUID id,int number,String range,long length,String hash,InputStream input){var preflight=session(service,id,true,false);open(preflight);var part=UploadRules.part(((Number)preflight.get("expected_size")).longValue(),number,range,length);String digest=UploadRules.sha(hash);var store=files.get();String key=store.receive(input,length,digest);return tx.execute(status->{rollback(key);var row=session(service,id,true,true);open(row);var prior=db.one("SELECT * FROM storage.upload_part WHERE upload_session_id=? AND part_no=?",id,number);if(prior!=null){if(!digest.equals(prior.get("sha256"))||length!=((Number)prior.get("byte_size")).longValue())throw ApiFault.conflict("相同分片序号内容不同");store.verifiedPrimary((String)prior.get("staging_key"),length,digest);store.rollbackNew(key);}else db.update("INSERT INTO storage.upload_part(upload_session_id,part_no,\"offset\",byte_size,sha256,staging_key) VALUES(?,?,?,?,?,?)",id,number,part.offset(),length,digest,key);return Sql.map("id",id,"partNo",number,"sha256",digest);});}
    /** 提交后由独立工作器检测；网络重试只返回或重新排队同一任务，不增加档案版本。 */
    @Transactional
    public Map<String,Object> complete(UUID service,UUID id,Map<String,Object> body){
        Inputs.only(body,"partCount","finalSha256");var row=session(service,id,true,true);long size=((Number)row.get("expected_size")).longValue();int count=Inputs.integer(body.get("partCount"),0,1,128);if(count!=UploadRules.count(size)||!UploadRules.sha(body.get("finalSha256")).equals(row.get("expected_sha256")))throw ApiFault.invalid("分片总数或最终摘要不一致");
        if("COMPLETE".equals(row.get("state")))return status(service,id);
        if("CHECK_PENDING".equals(row.get("state"))){var job=db.required("SELECT * FROM ops.job WHERE id=? FOR UPDATE",row.get("job_id"));if("FAILED".equals(job.get("state"))){if(((Number)job.get("attempt_count")).intValue()>=5)throw ApiFault.conflict("检测重试已达上限，请处理异常后新建上传");db.update("UPDATE ops.job SET state='PENDING',error_code=NULL WHERE id=?",job.get("id"));}return status(service,id);}
        open(row);var parts=db.rows("SELECT part_no,byte_size,\"offset\" FROM storage.upload_part WHERE upload_session_id=? ORDER BY part_no",id);if(parts.size()!=count)throw ApiFault.conflict("分片尚未完整收到");for(int i=0;i<parts.size();i++){var part=parts.get(i);long offset=i*UploadRules.PART_SIZE;if(((Number)part.get("part_no")).intValue()!=i+1||((Number)part.get("offset")).longValue()!=offset||((Number)part.get("byte_size")).longValue()!=Math.min(UploadRules.PART_SIZE,size-offset))throw ApiFault.conflict("分片范围不完整");}
        UUID job=UUID.randomUUID();db.update("INSERT INTO ops.job(id,job_type,module,business_ref,input_version,authorization_version,idempotency_key) VALUES(?,'SCAN_FILE_CHECK','ARCHIVE',?,1,1,?)",job,id.toString(),"SCAN:"+id);db.update("UPDATE storage.upload_session SET state='CHECK_PENDING',job_id=? WHERE id=?",job,id);return status(service,id);
    }
    /** 小批量租约调度，多个服务实例不会同时提交同一检测结果。 */
    @Scheduled(fixedDelayString="${platform.scan-intake.worker-delay-ms:5000}")
    public void tick(){if(!enabled)return;for(var job:db.rows("SELECT id FROM ops.job WHERE job_type='SCAN_FILE_CHECK' AND (state='PENDING' OR (state='RUNNING' AND lease_until<CURRENT_TIMESTAMP)) ORDER BY id LIMIT 2"))try{process((UUID)job.get("id"));}catch(Exception failure){
            // 领取之前的撤权或轮次变化也形成失败状态，不能长期阻塞队列的前两项。
            tx.executeWithoutResult(status->{int changed=db.update("UPDATE ops.job SET state='FAILED',error_code='SCAN_SCOPE_OR_PROTECTION_INVALID',lease_owner=NULL,lease_until=NULL WHERE id=? AND (state='PENDING' OR (state='RUNNING' AND lease_until<CURRENT_TIMESTAMP))",job.get("id"));if(changed>0){var context=db.one("SELECT s.service_identity_id,i.batch_id,i.id FROM ops.job j JOIN storage.upload_session s ON s.id=j.business_ref::uuid JOIN archive.scan_upload_binding u ON u.upload_session_id=s.id JOIN archive.scan_item i ON i.id=u.item_id WHERE j.id=?",job.get("id"));if(context!=null)intake.event((UUID)context.get("batch_id"),(UUID)context.get("id"),"FILE_CHECK_FAILED",null,(UUID)context.get("service_identity_id"),Sql.map("jobId",job.get("id"),"errorCode","SCAN_SCOPE_OR_PROTECTION_INVALID"));}});
        }}
    /** 任务租约冻结检测主体和全部输入。 */
    private record Work(/** 任务。 */ UUID job,/** 上传。 */ UUID upload,/** 设备主体。 */ UUID service,/** 独立检测身份。 */ UUID checker,/** 尝试。 */ UUID attempt,/** 随机租约。 */ String lease,/** 文件大小。 */ long size,/** 内容摘要。 */ String hash,/** 名称。 */ String name,/** 分片。 */ List<QuarantineFiles.SourcePart> parts) { }
    /** 可信工作器执行真实病毒检测和隔离 PDF 解析；设备自报检测通过无效。 */
    public void process(UUID jobId){
        Work work=tx.execute(status->{var metadata=db.required("SELECT business_ref FROM ops.job WHERE id=? AND job_type='SCAN_FILE_CHECK'",jobId);UUID upload=Inputs.uuid(metadata.get("business_ref"));var owner=db.required("SELECT service_identity_id FROM storage.upload_session WHERE id=?",upload);UUID service=(UUID)owner.get("service_identity_id");var row=session(service,upload,true,true);var job=db.required("SELECT *,lease_until<CURRENT_TIMESTAMP AS expired FROM ops.job WHERE id=? FOR UPDATE",jobId);if(!"CHECK_PENDING".equals(row.get("state"))||!("PENDING".equals(job.get("state"))||("RUNNING".equals(job.get("state"))&&Boolean.TRUE.equals(job.get("expired")))))throw ApiFault.conflict("任务正在执行或已经结束");UUID checker=checker(row);String lease=UUID.randomUUID().toString();UUID attempt=UUID.randomUUID();int number=((Number)job.get("attempt_count")).intValue()+1;db.update("UPDATE ops.job_attempt SET state='ABANDONED',ended_at=CURRENT_TIMESTAMP,sanitized_error='LEASE_EXPIRED' WHERE job_id=? AND state='RUNNING'",jobId);db.update("UPDATE ops.job SET state='RUNNING',attempt_count=?,lease_owner=?,lease_until=CURRENT_TIMESTAMP+interval '20 minutes' WHERE id=?",number,lease,jobId);db.update("INSERT INTO ops.job_attempt(id,job_id,attempt_no,worker_identity_id,lease_token) VALUES(?,?,?,?,?)",attempt,jobId,number,checker,Crypto.hash(lease));return new Work(jobId,upload,service,checker,attempt,lease,((Number)row.get("expected_size")).longValue(),(String)row.get("expected_sha256"),(String)row.get("original_name"),db.rows("SELECT * FROM storage.upload_part WHERE upload_session_id=? ORDER BY part_no",upload).stream().map(part->new QuarantineFiles.SourcePart((String)part.get("staging_key"),((Number)part.get("byte_size")).longValue(),(String)part.get("sha256"))).toList());});
        if(work==null)throw ApiFault.protection();
        try{
            var store=files.get();String key=store.assemble(work.parts(),work.size(),work.hash());var source=store.verifiedPrimary(key,work.size(),work.hash());var verdict=scanner.scan(source);if(verdict==ClamFileScanner.Verdict.UNAVAILABLE)throw ApiFault.protection();boolean clean=verdict==ClamFileScanner.Verdict.CLEAN&&"application/pdf".equals(FileMediaCheck.detect(source,work.name(),"application/pdf"));int pages=clean?runtime.withClient(client->client.pageCount(source,work.hash())):0;
            tx.executeWithoutResult(status->{rollback(key);var row=session(work.service(),work.upload(),true,true);checker(row);var job=db.required("SELECT *,lease_until>CURRENT_TIMESTAMP AS valid FROM ops.job WHERE id=? FOR UPDATE",work.job());if(!"RUNNING".equals(job.get("state"))||!work.lease().equals(job.get("lease_owner"))||!Boolean.TRUE.equals(job.get("valid")))throw ApiFault.conflict("检测租约失效");store.verifiedPrimary(key,work.size(),work.hash());UUID object=UUID.randomUUID();db.update("INSERT INTO storage.object(id,module,storage_key,sha256,byte_size,media_type,original_name,object_kind,state,service_identity_id,check_result_ref) VALUES(?,'ARCHIVE',?,?,?,'application/pdf',?,'ORIGINAL',?,?,?)",object,key,work.hash(),work.size(),work.name(),clean?"READY":"QUARANTINED",work.service(),work.attempt().toString());db.update("UPDATE storage.upload_session SET state=?,object_id=?,result_code=? WHERE id=?",clean?"COMPLETE":"REJECTED",object,clean?"CLEAN":"FILE_REJECTED",work.upload());db.update("UPDATE ops.job SET state=?,result_ref=?,error_code=?,lease_owner=NULL,lease_until=NULL WHERE id=?",clean?"SUCCEEDED":"FAILED",clean?"scan-pages:"+pages:null,clean?null:"FILE_REJECTED",work.job());db.update("UPDATE ops.job_attempt SET state=?,ended_at=CURRENT_TIMESTAMP,result_ref=?,sanitized_error=? WHERE id=?",clean?"SUCCEEDED":"FAILED",clean?"scan-pages:"+pages:null,clean?null:"FILE_REJECTED",work.attempt());intake.event((UUID)row.get("batch_id"),(UUID)row.get("item_id"),clean?"FILE_CHECKED":"FILE_REJECTED",null,work.service(),Sql.map("uploadId",work.upload(),"attemptId",work.attempt(),"pages",pages));});
        }catch(Exception failure){tx.executeWithoutResult(status->{int changed=db.update("UPDATE ops.job SET state='FAILED',error_code='SCAN_CHECK_FAILED',lease_owner=NULL,lease_until=NULL WHERE id=? AND lease_owner=? AND state='RUNNING'",work.job(),work.lease());if(changed>0){var item=db.required("SELECT i.batch_id,i.id FROM archive.scan_upload_binding b JOIN archive.scan_item i ON i.id=b.item_id WHERE b.upload_session_id=?",work.upload());intake.event((UUID)item.get("batch_id"),(UUID)item.get("id"),"FILE_CHECK_FAILED",null,work.service(),Sql.map("jobId",work.job(),"errorCode","SCAN_CHECK_FAILED"));}db.update("UPDATE ops.job_attempt SET state='FAILED',ended_at=CURRENT_TIMESTAMP,sanitized_error='SCAN_CHECK_FAILED' WHERE id=? AND state='RUNNING'",work.attempt());});if(failure instanceof ApiFault fault)throw fault;throw ApiFault.protection();}
    }
    /** 只有完整通过检测的本轮上传才能生成正式业务回执，重试不重复挂 PDF。 */
    @Transactional
    public Map<String,Object> receive(UUID service,Map<String,Object> body){
        Inputs.only(body,"eventId","deviceId","batchId","itemId","uploadSessionId","receiptKey","receivedPages","sha256");UUID batchId=Inputs.uuid(body.get("batchId")),itemId=Inputs.uuid(body.get("itemId")),upload=Inputs.uuid(body.get("uploadSessionId")),event=Inputs.uuid(body.get("eventId"));String key=Inputs.text(body,"receiptKey",128),digest=Crypto.hash(Crypto.json(body));var batch=intake.serviceBatch(service,batchId,false,true);if(!Inputs.uuid(body.get("deviceId")).equals(batch.get("device_id")))throw ApiFault.denied();
        var prior=db.one("SELECT * FROM archive.scan_receipt WHERE service_identity_id=? AND (event_id=? OR receipt_key=?)",service,event,key);if(prior!=null){if(!digest.equals(prior.get("request_digest")))throw ApiFault.conflict("回执键已用于其他内容");return receipt(prior);}
        intake.serviceBatch(service,batchId,true,true);var row=session(service,upload,true,true);if(!itemId.equals(row.get("item_id"))||!batchId.equals(row.get("batch_id")))throw ApiFault.denied();if(!"COMPLETE".equals(row.get("state"))||!UploadRules.sha(body.get("sha256")).equals(row.get("expected_sha256")))throw ApiFault.conflict("文件尚未通过检测或摘要不一致");var job=db.required("SELECT * FROM ops.job WHERE id=? AND state='SUCCEEDED'",row.get("job_id"));int pages=Integer.parseInt(((String)job.get("result_ref")).substring("scan-pages:".length()));if(pages!=Inputs.integer(body.get("receivedPages"),0,1,10000))throw ApiFault.invalid("设备页数与服务器实测不一致");
        var item=intake.item(itemId);if(!Set.of("WAITING","REWORK").contains(item.get("state")))throw ApiFault.conflict("该项已接收");var record=intake.record((UUID)item.get("record_id"),(UUID)batch.get("department_id"),true);var object=db.required("SELECT * FROM storage.object WHERE id=? AND state='READY' AND service_identity_id=?",row.get("object_id"),service);files.get().verifiedPrimary((String)object.get("storage_key"),((Number)object.get("byte_size")).longValue(),(String)object.get("sha256"));
        UUID pdf=UUID.randomUUID(),revision=UUID.randomUUID(),id=UUID.randomUUID();int next=(int)db.count("SELECT COALESCE(max(version_no),0)+1 FROM archive.pdf_version WHERE record_id=?",record.get("id"));db.update("INSERT INTO archive.pdf_version(id,record_id,version_no,object_id,source,correction_reason,created_by,page_count) VALUES(?,?,?,?,'SCAN',?,?,?)",pdf,record.get("id"),next,object.get("id"),"扫描批次 "+batchId+" 第 "+item.get("generation")+" 轮",batch.get("created_by"),pages);
        int revisionNo=(int)db.count("SELECT COALESCE(max(revision_no),0)+1 FROM archive.record_revision WHERE record_id=?",record.get("id"));var metadata=db.required("SELECT metadata_snapshot FROM archive.record_revision WHERE id=?",record.get("candidate_revision_id"));db.update("INSERT INTO archive.record_revision(id,record_id,revision_no,pdf_version_id,metadata_snapshot,template_version_id,created_by) VALUES(?,?,?,?,?::jsonb,?,?)",revision,record.get("id"),revisionNo,pdf,metadata.get("metadata_snapshot").toString(),record.get("template_version_id"),batch.get("created_by"));db.update("UPDATE archive.record SET candidate_revision_id=?,row_version=row_version+1 WHERE id=?",revision,record.get("id"));db.update("INSERT INTO storage.object_reference(id,object_id,owner_type,owner_id,reference_kind) VALUES(?,?,'ARCHIVE_PDF',?,'BUSINESS')",UUID.randomUUID(),object.get("id"),pdf);db.update("UPDATE archive.scan_item SET state='RECEIVED',pdf_version_id=?,received_pages=?,row_version=row_version+1 WHERE id=?",pdf,pages,itemId);
        db.update("INSERT INTO archive.scan_receipt(id,service_identity_id,event_id,batch_id,item_id,upload_session_id,receipt_key,request_digest,pdf_version_id) VALUES(?,?,?,?,?,?,?,?,?)",id,service,event,batchId,itemId,upload,key,digest,pdf);intake.event(batchId,itemId,"RECEIVED",null,service,Sql.map("receiptId",id,"pdfVersionId",pdf,"sha256",body.get("sha256"),"pages",pages));intake.refresh(batchId);return receipt(db.required("SELECT * FROM archive.scan_receipt WHERE id=?",id));
    }
    /** 会话绑定轮次在收流前后均核对，纠正或返工后旧会话不得继续。 */
    private Map<String,Object> session(UUID service,UUID id,boolean write,boolean lock){var mapping=db.required("SELECT b.*,i.batch_id,i.record_id FROM archive.scan_upload_binding b JOIN archive.scan_item i ON i.id=b.item_id JOIN storage.upload_session s ON s.id=b.upload_session_id WHERE b.upload_session_id=? AND s.service_identity_id=?",id,service);var batch=intake.serviceBatch(service,(UUID)mapping.get("batch_id"),write,lock);var item=db.required("SELECT * FROM archive.scan_item WHERE id=?"+(lock?" FOR UPDATE":""),mapping.get("item_id"));var record=db.required("SELECT row_version FROM archive.record WHERE id=?"+(lock?" FOR UPDATE":""),mapping.get("record_id"));var row=db.required("SELECT *,expires_at>CURRENT_TIMESTAMP AS valid FROM storage.upload_session WHERE id=? AND service_identity_id=?"+(lock?" FOR UPDATE":""),id,service);
        // 已挂接的 COMPLETE 会话仍可查询原回执；其余会话必须保留创建时的目录和明细版本。
        boolean received=db.count("SELECT count(*) FROM archive.scan_receipt WHERE upload_session_id=?",id)>0;
        if(!received&&(!Objects.equals(item.get("generation"),mapping.get("generation"))||!Objects.equals(item.get("row_version"),mapping.get("item_version"))||!Objects.equals(record.get("row_version"),mapping.get("record_version"))))throw ApiFault.conflict("扫描项或目录已变化，请使用纠正后的新上传");
        row.put("batch_id",mapping.get("batch_id"));row.put("item_id",mapping.get("item_id"));row.put("department_id",batch.get("department_id"));return row;
    }
    /** 正常分片只进入尚未过期的开放会话。 */
    private void open(Map<String,Object> row){if(!"OPEN".equals(row.get("state"))||!Boolean.TRUE.equals(row.get("valid")))throw ApiFault.conflict("上传已结束或过期");}
    /** 检测工作器使用独立受限身份，设备账号不能自报干净。 */
    private UUID checker(Map<String,Object> upload){UUID id=Inputs.uuid(scannerId);db.required("SELECT id FROM iam.service_identity WHERE id=? AND service_type='FILE_CHECK' AND allowed_module='ARCHIVE' AND ?=ANY(department_scope) AND 'FILE_CHECK'=ANY(allowed_actions) AND status='ACTIVE' AND valid_until>CURRENT_TIMESTAMP FOR SHARE",id,upload.get("department_id"));return id;}
    /** 明确回滚时只清理本次新键；提交结果未知时保留供核查。 */
    private void rollback(String key){TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCompletion(int state){if(state==STATUS_ROLLED_BACK)files.get().rollbackNew(key);}});}
    /** 设备接收回执只含固定标识和待质检状态，不含目录正文。 */
    private Map<String,Object> receipt(Map<String,Object> row){return Sql.map("id",row.get("id"),"batchId",row.get("batch_id"),"itemId",row.get("item_id"),"receiptKey",row.get("receipt_key"),"state","RECEIVED","receivedAt",row.get("received_at"));}
}
